'use strict';
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function deferred() {
  let resolve, reject;
  const promise = new Promise((a, b) => { resolve = a; reject = b; });
  return { promise, resolve, reject };
}
function scripted(results) {
  let calls = 0;
  const load = () => results[calls++];
  return { load, calls: () => calls };
}

(async () => {
  // set during load wins; old completion doesn't overwrite or restart TTL; expiry starts new load
  {
    let t = 0;
    const g = deferred();
    const s = scripted([g.promise, 'new']);
    const c = createCache({ load: s.load, ttlMs: 10, now: () => t });
    const old = c.get('k'); await tick();
    c.set('k', 'manual');
    t = 5; g.resolve('stale');
    assert.equal(await old, 'stale');
    assert.equal(await c.get('k'), 'manual');
    t = 10; // set at 0 + 10 -> expired even though old flight committed at 5
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'new');
    assert.equal(s.calls(), 2);
  }
  // set expires while old load pending -> new load, not detached one
  {
    let t = 0;
    const g = deferred();
    const s = scripted([g.promise, 'second']);
    const c = createCache({ load: s.load, ttlMs: 10, now: () => t });
    const old = c.get('k'); await tick();
    c.set('k', 'manual'); t = 10;
    assert.equal(await c.get('k'), 'second');
    g.resolve('stale'); assert.equal(await old, 'stale');
    assert.equal(await c.get('k'), 'second');
  }
  // rejection not cached, all waiters same reason, retry works
  {
    const reason = { nonError: true };
    const s = scripted([Promise.reject(reason), 'ok']);
    const c = createCache({ load: s.load, now: () => 0 });
    const a = c.get('k'), b = c.get('k');
    await assert.rejects(a, r => r === reason);
    await assert.rejects(b, r => r === reason);
    assert.equal(await c.get('k'), 'ok');
    assert.equal(s.calls(), 2);
  }
  // sync throw
  {
    let n = 0;
    const c = createCache({ load: () => { if (n++ === 0) throw 'boom'; return 1; }, now: () => 0 });
    await assert.rejects(c.get('k'), r => r === 'boom');
    assert.equal(await c.get('k'), 1);
  }
  // obsolete flight (resolve or reject) doesn't detach newer flight
  for (const mode of ['resolve', 'reject']) {
    const g1 = deferred(), g2 = deferred();
    const s = scripted([g1.promise, g2.promise, 'third']);
    const c = createCache({ load: s.load, now: () => 0 });
    const r1 = c.get('k'); await tick();
    c.invalidate('k');
    const r2 = c.get('k'); await tick();
    g1[mode]('old'); await (mode === 'resolve' ? r1 : r1.catch(() => {}));
    const r3 = c.get('k');
    assert.equal(r3, r2); // still joins newer flight
    g2.resolve('new');
    assert.equal(await r3, 'new');
    assert.equal(await c.get('k'), 'new');
    assert.equal(s.calls(), 2);
  }
  // repeated invalidations with no stored value are separate barriers
  {
    const g1 = deferred(), g2 = deferred();
    const s = scripted([g1.promise, g2.promise, 'third']);
    const c = createCache({ load: s.load, now: () => 0 });
    c.get('k'); await tick();
    c.invalidate('k');
    c.get('k'); await tick();
    c.invalidate('k');
    const r3 = c.get('k');
    g1.resolve('a'); g2.resolve('b');
    assert.equal(await r3, 'third');
    assert.equal(await c.get('k'), 'third');
  }
  // clear detaches all flights
  {
    const g = deferred();
    const s = scripted([g.promise, 'fresh']);
    const c = createCache({ load: s.load, now: () => 0 });
    const old = c.get('k'); await tick();
    c.clear(); g.resolve('stale'); await old;
    assert.equal(await c.get('k'), 'fresh');
  }
  // load calling invalidate / set synchronously
  {
    let n = 0;
    let c;
    c = createCache({ now: () => 0, load: k => { n++; if (n === 1) c.invalidate(k); return 'v' + n; } });
    assert.equal(await c.get('k'), 'v1');
    assert.equal(await c.get('k'), 'v2');
    let m = 0;
    const c2 = createCache({ now: () => 0, load: k => { m++; c2.set(k, 'manual'); return 'loaded'; } });
    assert.equal(await c2.get('k'), 'loaded');
    assert.equal(await c2.get('k'), 'manual');
    assert.equal(m, 1);
  }
  // load reads own key without awaiting -> joins
  {
    let n = 0, inner;
    const c = createCache({ now: () => 0, load: k => { n++; inner = c.get(k); return 'x'; } });
    const outer = c.get('k');
    assert.equal(await outer, 'x');
    assert.equal(inner, outer);
    assert.equal(n, 1);
  }
  // ttl 0 dedups unsettled, never reuses settled
  {
    const g = deferred();
    const s = scripted([g.promise, 'b']);
    const c = createCache({ load: s.load, ttlMs: 0, now: () => 0 });
    const a1 = c.get('k'), a2 = c.get('k');
    g.resolve('a');
    assert.equal(await a1, 'a'); assert.equal(await a2, 'a');
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'b');
    assert.equal(s.calls(), 2);
  }
  console.log('all scratch checks passed');
})().catch(e => { console.error(e); process.exit(1); });

